fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    let max_len = m.max(n);

    let mut out_a = Vec::with_capacity(max_len);
    let mut out_b = Vec::with_capacity(max_len);

    // For each index, apply broadcasting rules:
    // If length == 1, use a[0] or b[0]
    // Else use a[i] or b[i]
    for i in 0..max_len {
        let val_a = if m == 1 { a[0] } else { a[i] };
        let val_b = if n == 1 { b[0] } else { b[i] };
        out_a.push(val_a);
        out_b.push(val_b);
    }

    (out_a, out_b)
}